{
"spec": "This plan adds CSV and Markdown output formats to the exporter tool, implementing header-based rows, standard CSV quoting, and Markdown table escaping including pipe character handling. It introduces a `--fields` CLI argument to select and order specific columns across all formats, ensuring missing values are rendered as empty cells. The `--list-formats` command is updated to include the new formats, and the CLI is enhanced to write to standard output when no file path is provided. Existing JSON and text formats remain untouched to preserve byte-for-byte compatibility, relying on the existing registration mechanism for new formats.",
"stack": "Python, csv, markdown, pytest",
"tasks": [
  {
    "id": 1,
    "title": "Implement CSV format writer with header, quoting, and missing value handling",
    "files": [
      "exporter/formats/csv_fmt.py"
    ],
    "test": "tests/test_formats.py: test_csv_output checks header row, quoted fields, and empty cells for missing keys.",
    "check": "python -c \"from exporter.formats.csv_fmt import write_csv; import io; f=io.StringIO(); write_csv([{'a':1,'b':2}], f); print(f.getvalue())\"",
    "expect": "a,b\n1,2"
  },
  {
    "id": 2,
    "title": "Implement Markdown format writer with table structure and pipe escaping",
    "files": [
      "exporter/formats/markdown_fmt.py"
    ],
    "test": "tests/test_formats.py: test_markdown_output checks table headers, separator, and escaped pipes.",
    "check": "python -c \"from exporter.formats.markdown_fmt import write_md; import io; f=io.StringIO(); write_md([{'a':1,'b':'x|y'}], f); print(f.getvalue())\"",
    "expect": "| a | b |\n|---|---|\n| 1 | x\\|y |"
  },
  {
    "id": 3,
    "title": "Register CSV and Markdown formats and update settings extensions",
    "files": [
      "exporter/formats/__init__.py",
      "exporter/settings.py"
    ],
    "test": "tests/test_formats.py: test_registered checks that 'csv' and 'markdown' are available in REGISTRY and EXTENSIONS.",
    "check": "python -c \"from exporter import formats; print(formats.names())\"",
    "expect": "['csv', 'json', 'markdown', 'text']"
  },
  {
    "id": 4,
    "title": "Add --fields argument parsing and field selection logic to CLI",
    "files": [
      "exporter/cli.py"
    ],
    "test": "tests/test_formats.py: test_field_selection checks that only specified fields appear in output in correct order.",
    "check": "python -c \"from exporter import cli; import tempfile, json, os; d=tempfile.mkdtemp(); src=os.path.join(d,'in.json'); dst=os.path.join(d,'out.csv'); open(src,'w').write(json.dumps([{'a':1,'b':2,'c':3}])); cli.main(['--format','csv','--fields','b,a',src,d]); print(open(dst).read())\"",
    "expect": "b,a\n2,1"
  },
  {
    "id": 5,
    "title": "Update --list-formats to include new CSV and Markdown formats",
    "files": [
      "exporter/cli.py"
    ],
    "test": "tests/test_formats.py: test_list_formats checks that output contains 'csv' and 'markdown'.",
    "check": "python -c \"from exporter import cli; cli.main(['--list-formats'])\"",
    "expect": "csv(.csv) json(.json) markdown(.md) text(.txt)"
  },
  {
    "id": 6,
    "title": "Implement standard output writing when no output path is provided",
    "files": [
      "exporter/cli.py"
    ],
    "test": "tests/test_formats.py: test_stdout_output checks that output is written to stdout when no path is given.",
    "check": "python -c \"from exporter import cli; import tempfile, json, os; d=tempfile.mkdtemp(); src=os.path.join(d,'in.json'); open(src,'w').write(json.dumps([{'a':1}])); cli.main(['--format','json',src])\"",
    "expect": "[\n  {\n    \"a\": 1\n  }\n]"
  },
  {
    "id": 7,
    "title": "Verify existing JSON output remains unchanged after new changes",
    "files": [
      "tests/test_formats.py"
    ],
    "test": "tests/test_formats.py: test_json_round_trip passes, ensuring byte-for-byte compatibility.",
    "check": "python -m pytest tests/test_formats.py::test_json_round_trip -v",
    "expect": "PASSED"
  }
]
}
